if (!process.argv.includes("--skip-preflight")) {
  // 继承父进程的 OV_MAX_COMMIT_QUEUE（如 import-local-sources 外层设的 64），未设时默认 12
  const pf = spawnSync(
    process.execPath,
    [path.join(__dir, "scripts/ov-import-preflight.mjs")],
    {
      cwd: __dir,
      stdio: "inherit",
      env: {
        ...process.env,
        OV_MAX_COMMIT_QUEUE: process.env.OV_MAX_COMMIT_QUEUE || "12",
      },
    }
  );
